mapper.update:
UPDATE app_chat_run
SET lease_owner = #{newLeaseOwner},
    lease_expires_at = #{newLeaseExpiresAt},
    fencing_token = fencing_token + 1,
    attempt_count = attempt_count + 1,
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND lease_owner = #{leaseOwner}
  AND fencing_token = #{fencingToken}
  AND status = 'IN_PROGRESS'
  AND phase = 'PREPARING'
  AND lease_expires_at <= #{now}

UPDATE app_chat_run
SET status = 'UNCERTAIN',
    failure_code = 'MODEL_RESULT_UNCERTAIN',
    failure_summary = '模型调用已派发但结果尚未确认',
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND lease_owner = #{leaseOwner}
  AND fencing_token = #{fencingToken}
  AND status = 'IN_PROGRESS'
  AND phase = 'MODEL_DISPATCHED'
  AND lease_expires_at <= #{now}

UPDATE app_chat_run
SET phase = 'MODEL_DISPATCHED', lease_expires_at = #{leaseExpiresAt}, updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND lease_owner = #{leaseOwner}
  AND fencing_token = #{fencingToken}
  AND status = 'IN_PROGRESS'
  AND phase = 'PREPARING'
  AND lease_expires_at > #{now}

UPDATE app_chat_run
SET status = 'IN_PROGRESS',
    phase = 'RESULT_RECEIVED',
    finalization_json = CAST(#{finalizationJson} AS jsonb),
    finalization_attempt_count = 1,
    finalization_cycle_attempt_count = 1,
    lease_expires_at = #{leaseExpiresAt},
    failure_code = NULL,
    failure_summary = NULL,
    failure_trace_id = NULL,
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND lease_owner = #{leaseOwner}
  AND fencing_token = #{fencingToken}
  AND (
      (status = 'IN_PROGRESS' AND phase IN ('PREPARING', 'MODEL_DISPATCHED'))
      OR (status = 'UNCERTAIN' AND phase = 'MODEL_DISPATCHED')
  )

UPDATE app_chat_run
SET lease_owner = #{newLeaseOwner},
    lease_expires_at = #{newLeaseExpiresAt},
    fencing_token = fencing_token + 1,
    attempt_count = attempt_count + 1,
    finalization_attempt_count = finalization_attempt_count + 1,
    finalization_cycle_attempt_count = finalization_cycle_attempt_count + 1,
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND lease_owner = #{leaseOwner}
  AND fencing_token = #{fencingToken}
  AND status = 'IN_PROGRESS'
  AND phase = 'RESULT_RECEIVED'
  AND finalization_json IS NOT NULL
  AND finalization_cycle_attempt_count < 3
  AND lease_expires_at <= #{now}

UPDATE app_chat_run
SET status = CASE
        WHEN finalization_cycle_attempt_count >= #{maxAttempts} THEN 'DEAD_LETTER'
        ELSE 'IN_PROGRESS'
    END,
    lease_expires_at = CASE
        WHEN finalization_cycle_attempt_count >= #{maxAttempts} THEN #{now}
        ELSE #{now} + (
            LEAST(finalization_cycle_attempt_count, #{maxAttempts}) * #{baseBackoffSeconds}
        ) * INTERVAL '1 second'
    END,
    failure_code = #{failureCode},
    failure_summary = #{failureSummary},
    failure_trace_id = #{traceId},
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND lease_owner = #{leaseOwner}
  AND fencing_token = #{fencingToken}
  AND status = 'IN_PROGRESS'
  AND phase = 'RESULT_RECEIVED'
  AND finalization_json IS NOT NULL

