INSERT INTO app_chat_run_replay_request (
    tenant_id, run_id, replay_request_id, actor_id, reason, created_at
) VALUES (
    #{tenantId}, #{runId}, #{replayRequestId}, #{actorId}, #{reason}, #{createdAt}
)
ON CONFLICT (tenant_id, replay_request_id) DO NOTHING

