UPDATE app_chat_run
SET status = 'QUARANTINED',
    finalization_json = NULL,
    failure_code = #{failureCode},
    failure_summary = #{failureSummary},
    failure_trace_id = NULL,
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND lease_owner = #{leaseOwner}
  AND fencing_token = #{fencingToken}
  AND status = 'IN_PROGRESS'
  AND phase = 'RESULT_RECEIVED'
  AND finalization_json IS NOT NULL

UPDATE app_chat_run
SET status = 'COMPLETED', result_json = CAST(#{resultJson} AS jsonb),
    finalization_json = NULL, failure_code = NULL, failure_summary = NULL,
    failure_trace_id = NULL,
    completed_at = #{now}, updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND lease_owner = #{leaseOwner}
  AND fencing_token = #{fencingToken}
  AND status = 'IN_PROGRESS'
  AND phase = 'RESULT_RECEIVED'
  AND finalization_json IS NOT NULL

UPDATE app_chat_run
SET status = 'FAILED', failure_code = #{failureCode}, failure_summary = #{failureSummary}, updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND lease_owner = #{leaseOwner}
  AND fencing_token = #{fencingToken}
  AND status = 'IN_PROGRESS'
  AND phase = 'PREPARING'

UPDATE app_chat_run
SET status = 'UNCERTAIN', failure_code = #{failureCode}, failure_summary = #{failureSummary}, updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND run_id = #{runId}
  AND lease_owner = #{leaseOwner}
  AND fencing_token = #{fencingToken}
  AND status = 'IN_PROGRESS'
  AND phase = 'MODEL_DISPATCHED'
